export function median(values: number[]) {
  if (!values.length) return null
  const sorted = [...values].sort((a, b) => a - b)
  const mid = sorted.length >> 1
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2
}

export function jitter(values: number[]) {
  if (values.length < 2) return null
  let sum = 0
  for (let i = 1; i < values.length; i++) sum += Math.abs(values[i] - values[i - 1])
  return sum / (values.length - 1)
}

const toMbps = (bytes: number, ms: number) => (ms > 0 ? (bytes * 8) / (ms / 1000) / 1_000_000 : 0)

function windowMbps(points: Point[], windowMs = 1000) {
  const last = points.at(-1)
  if (!last || points.length < 2) return 0
  let base = points[0]
  for (let i = points.length - 2; i >= 0; i--) {
    base = points[i]
    if (last.t - points[i].t >= windowMs) break
  }
  return toMbps(last.bytes - base.bytes, last.t - base.t)
}

function finalMbps(points: Point[], warmupMs: number) {
  const first = points[0]
  const last = points.at(-1)
  if (!first || !last || last.bytes === 0 || last.t === first.t) return null
  const start = points.find((p) => p.t - first.t >= warmupMs && p.t < last.t) ?? first
  return toMbps(last.bytes - start.bytes, last.t - start.t)
}

export const GAUGE_TICKS = [0, 1, 5, 10, 50, 100, 250, 500, 1000] as const

export function gaugeFraction(mbps: number) {
  if (!(mbps > 0)) return 0
  const ticks = GAUGE_TICKS
  if (mbps >= ticks[ticks.length - 1]) return 1
  const step = 1 / (ticks.length - 1)
  for (let i = 1; i < ticks.length; i++) {
    if (mbps <= ticks[i]) return (i - 1 + (mbps - ticks[i - 1]) / (ticks[i] - ticks[i - 1])) * step
  }
  return 1
}

export function formatMbps(mbps: number | null) {
  if (mbps === null) return '—'
  if (mbps >= 100) return mbps.toFixed(0)
  if (mbps >= 10) return mbps.toFixed(1)
  return mbps.toFixed(2)
}

export function speedRating(mbps: number | null) {
  if (mbps === null) return null
  if (mbps < 5) return { label: 'Slow — basic browsing only', color: '#f87171' }
  if (mbps < 25) return { label: 'OK — fine for HD video', color: '#fbbf24' }
  if (mbps < 100) return { label: 'Good — 4K streaming and calls', color: '#22c55e' }
  return { label: 'Great — handles anything', color: '#22c55e' }
}

/** Round trips for the sample run; the first also pays for DNS and TLS, so it is discarded. */
const RTTS = [46, 19, 18, 21, 17, 19, 23, 18, 20, 19, 18, 24, 19]
export const PING_STEPS = RTTS.slice(1, LATENCY_SAMPLES + 1).map((_, i, kept) => {
  const seen = kept.slice(0, i + 1)
  return { ping: median(seen) as number, jitter: jitter(seen) ?? 0 }
})
export const PING = PING_STEPS[PING_STEPS.length - 1]

/** A sample line: TCP ramp-up, then a plateau with a little wobble. */
function simulate(durationMs: number, plateauMbps: number, rampMs: number, seed: number) {
  const points: Point[] = [{ t: 0, bytes: 0 }]
  let bytes = 0
  for (let t = TICK_MS; t <= durationMs; t += TICK_MS) {
    const ramp = 1 - Math.exp(-t / rampMs)
    const wobble = 1 + Math.sin(t / 370 + seed) * 0.04 + Math.sin(t / 130 + seed * 2) * 0.03
    bytes += ((plateauMbps * ramp * wobble * 1_000_000) / 8) * (TICK_MS / 1000)
    points.push({ t, bytes: Math.round(bytes) })
  }
  const live = points.map((_, i) => windowMbps(points.slice(0, i + 1)))
  return { points, live, final: finalMbps(points, WARMUP_MS) as number, bytes: Math.round(bytes) }
}

