export const CHART = { w: 280, h: 52, seconds: (DOWNLOAD_MS + UPLOAD_MS) / 1000 }
const CHART_MAX = Math.max(...DOWNLOAD.live) * 1.1
function line(live: number[], offsetMs: number) {
  return live
    .map((mbps, i) => {
      const x = ((offsetMs + i * TICK_MS) / 1000 / CHART.seconds) * CHART.w
      const y = CHART.h - (mbps / CHART_MAX) * (CHART.h - 4)
      return `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`
    })
    .join('')
}
export const DOWN_LINE = line(DOWNLOAD.live, 0)
export const UP_LINE = line(UPLOAD.live, DOWNLOAD_MS)
export const DOWN_END_X = (DOWNLOAD_MS / 1000 / CHART.seconds) * CHART.w

